def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                positions.setdefault(grid[r][c], set()).add((r, c))

    for color, cells in positions.items():
        for r, c in cells:
            neighbors = [
                (rr, cc) for rr in range(max(0, r - 1), min(h, r + 2))
                for cc in range(max(0, c - 1), min(w, c + 2))
                if (rr, cc) != (r, c) and (rr, cc) in cells
            ]
            # Extend only exposed endpoints of same-color strokes.
            if len(neighbors) != 1:
                continue

            # Endpoints touching another color are anchored, not extended.
            if any(
                grid[rr][cc] != bg and grid[rr][cc] != color
                for rr in range(max(0, r - 1), min(h, r + 2))
                for cc in range(max(0, c - 1), min(w, c + 2))
            ):
                continue

            nr, nc = neighbors[0]
            dr = (r > nr) - (r < nr)
            dc = (c > nc) - (c < nc)
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] == bg:
                    out[rr][cc] = color
                rr += dr
                cc += dc

    return out
